(()=>{document.documentElement.classList.add("js");const e=document.querySelector("[data-nav-toggle]"),t=document.querySelector("[data-nav-menu]");if(!e||!t)return;e.addEventListener("click",()=>{const n=e.getAttribute("aria-expanded")==="true";e.setAttribute("aria-expanded",String(!n)),t.classList.toggle("is-open",!n)}),t.addEventListener("keydown",n=>{n.key==="Escape"&&(e.setAttribute("aria-expanded","false"),t.classList.remove("is-open"),e.focus())})})()